export const roles=['Project manager','Analyst','Engineer','QA'];
export function days(start,end){const result=[];for(let d=new Date(start+'T12:00:00Z');d<=new Date(end+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+1)){if(d.getUTCDay()!==0&&d.getUTCDay()!==6)result.push(d.toISOString().slice(0,10));if(result.length>730)break}return result}
export function capacity(person,date){return person.leave.some(l=>date>=l.start&&date<=l.end)?0:person.capacity}
export function load(state,id,date,exclude){return state.projects.filter(p=>p.id!==exclude&&date>=p.start&&date<=p.end).reduce((sum,p)=>sum+p.assignments.filter(a=>a.personId===id).reduce((s,a)=>s+a.hours,0),0)}
export function utilization(state,person,start,end){const dates=days(start,end);const cap=dates.reduce((s,d)=>s+capacity(person,d),0);const used=dates.reduce((s,d)=>s+load(state,person.id,d),0);return {cap,used,percent:cap?Math.round(100*used/cap):used?100:0,conflicts:dates.filter(d=>load(state,person.id,d)>capacity(person,d)).length}}
export function recommend(state,project){const dates=days(project.start,project.end);return roles.map(role=>{const hours=project.effort[role]/(dates.length||1);const candidates=state.people.filter(p=>p.role===role&&p.level>=project.level).map(p=>{const skill=p.skills.includes(project.skill);const spare=dates.map(d=>capacity(p,d)-load(state,p.id,d,project.id));const available=Math.max(0,Math.min(...spare));const feasible=dates.length>0&&available+0.001>=hours;const avg=spare.reduce((a,b)=>a+b,0)/(dates.length||1);return {personId:p.id,name:p.name,skill,feasible,available,hours,score:Math.round((skill?40:0)+Math.min(40,avg/p.capacity*40)+(p.level-project.level)*5),reason:!feasible?'Insufficient capacity during this window':skill?'Domain match · capacity verified':'Transferable expertise · capacity verified'}}).sort((a,b)=>Number(b.feasible)-Number(a.feasible)||b.score-a.score||a.name.localeCompare(b.name));return {role,hours,candidates,selected:candidates.find(c=>c.feasible)?.personId||''}})}
export function validateSquad(state,project,assignments){if(!days(project.start,project.end).length)return 'Choose a window containing working days.';if(assignments.length!==roles.length)return 'Assign all four roles before applying.';for(const role of roles){const a=assignments.find(a=>a.role===role);const p=state.people.find(p=>p.id===a?.personId);if(!p||p.role!==role||p.level<project.level)return 'Every role needs a specialist at the required level.';if(a.hours+0.001<project.effort[role]/days(project.start,project.end).length)return 'Allocation does not cover project effort.';if(days(project.start,project.end).some(d=>load(state,p.id,d,project.id)+a.hours>capacity(p,d)+0.001))return p.name+' has a capacity conflict. Adjust the window or squad.'}return null}
